import{_ as n,o as r,c as i,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const c=JSON.parse('{"title":"Frühere Änderungen an Grundschulzeugnissen nachschlagen","description":"","frontmatter":{"title":"Frühere Änderungen an Grundschulzeugnissen nachschlagen","source_pageid":1458,"source_revision":5860},"headers":[],"relativePath":"zeugnisse/grundschule/grundschulzeugnisse-versionsgeschichte-tutorial.md","filePath":"zeugnisse/grundschule/grundschulzeugnisse-versionsgeschichte-tutorial.md"}'),t={name:"zeugnisse/grundschule/grundschulzeugnisse-versionsgeschichte-tutorial.md"};function s(u,e,l,h,g,d){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="fruhere-anderungen-an-grundschulzeugnissen-nachschlagen" tabindex="-1">Frühere Änderungen an Grundschulzeugnissen nachschlagen <a class="header-anchor" href="#fruhere-anderungen-an-grundschulzeugnissen-nachschlagen" aria-label="Permalink to &quot;Frühere Änderungen an Grundschulzeugnissen nachschlagen&quot;">​</a></h1><p>Lesen Sie die übernommene Versionsgeschichte der Grundschulformulare. Die Einträge dokumentieren frühere Änderungen an Reports und ihren Einstellungen.</p><h2 id="version-12-12-2023" tabindex="-1">Version 12.12.2023 <a class="header-anchor" href="#version-12-12-2023" aria-label="Permalink to &quot;Version 12.12.2023&quot;">​</a></h2><h3 id="gs-textzeugnisse" tabindex="-1">GS-Textzeugnisse <a class="header-anchor" href="#gs-textzeugnisse" aria-label="Permalink to &quot;GS-Textzeugnisse&quot;">​</a></h3><ul><li>Für den Jahrgang 04 gibt es nun Option, im Halbjahreszeugnis die Übergangsempfehlung auf Seite 2 nach Anlage „Schulformempfehlung“ gemäß VVzAO-GS zu drucken.<br> Konkrete Angabe in der HybridzeugnisEinstellungen.ini-Datei: SFESeite2 (Durch Setzen eines Semikolons kann die Option deaktiviert werden).</li><li>Der Abstand nach dem Notenblock kann nun über die HybridzeugnisEinstellungen.ini-Datei gesteuert werden. Dies ist vor allem für einseitige Zeugnisse der Jahrgangstufe 4.2 sinnvoll.<br> Konkrete Angabe in der Ini-Datei: AbstandNachNotenblock=15</li><li>Die Fachbezeichnung „Deutsch“ wurde doppelt aufgelistet, sofern die Option „Auf Zeugnis“ bei den Fächern SG, LE und RS deaktiviert war. Dies ist nun behoben.</li><li>über die HybridzeugnisEinstellungen.ini-Datei kann nun die Schriftart festgesetzt werden. Die Schriftart des Schulkopfes bleibt von der Einstellung unberührt.<br> Konkrete Angabe in der Ini-Datei: Schriftart=Calibri</li></ul><h3 id="anlage-„schulformempfehlung" tabindex="-1">Anlage „Schulformempfehlung“ <a class="header-anchor" href="#anlage-„schulformempfehlung" aria-label="Permalink to &quot;Anlage „Schulformempfehlung“&quot;">​</a></h3><ul><li>Im Zeugnisordner der GS-Textzeugnisse wurde ein separater Report Anlage_Schulformempfehlung.rtm nach Anlage „Schulformempfehlung“ gemäß VVzAO-GS hinzugefügt.</li></ul><h3 id="gs-ankreuzzeugnis" tabindex="-1">GS-Ankreuzzeugnis <a class="header-anchor" href="#gs-ankreuzzeugnis" aria-label="Permalink to &quot;GS-Ankreuzzeugnis&quot;">​</a></h3><ul><li>Die Überschrift „Bemerkung“ für den ASV-Bemerkungstext wurde nicht auf invisible gestellt, nachdem ein Schüler eine Bemerkung für das ASV auf dem Zeugnis hat. Dies ist nun behoben.</li></ul><h3 id="alle-zeugnisse" tabindex="-1">Alle Zeugnisse <a class="header-anchor" href="#alle-zeugnisse" aria-label="Permalink to &quot;Alle Zeugnisse&quot;">​</a></h3><p>Die Floskel für SuS mit Förderschwerpunkt wurde angepasst: FSP: Lernen + zieldifferent: „… wurde im Förderschwerpunkt Lernen … im zieldifferenten Bildungsgang Lernen….“ FSP: geistige Entwicklung + zieldifferent: „… Förderschwerpunkt geistige Entwicklung … zieldifferenten Bildungsgang geistige Entwicklung….“ Sonst: „… Förderschwerpunkt xxx … im (zieldifferenten) Bildungsgang Grundschule….“ Hinweis: Lernen und geistige Entwicklung muss für den zieldifferenten Bildungsgang als FSP1 eingetragen sein.</p><h3 id="gs-ankreuzzeugnis-mit-notenblock-rtm" tabindex="-1">GS-AnkreuzZeugnis_mit_Notenblock.rtm <a class="header-anchor" href="#gs-ankreuzzeugnis-mit-notenblock-rtm" aria-label="Permalink to &quot;GS-AnkreuzZeugnis_mit_Notenblock.rtm&quot;">​</a></h3><ul><li>Zeilenumbruch nach dem Bemerkungstext für ASV eingefügt.</li></ul><h2 id="version-15-05-2023" tabindex="-1">Version 15.05.2023 <a class="header-anchor" href="#version-15-05-2023" aria-label="Permalink to &quot;Version 15.05.2023&quot;">​</a></h2><h3 id="ini-dateien" tabindex="-1">Ini-Dateien <a class="header-anchor" href="#ini-dateien" aria-label="Permalink to &quot;Ini-Dateien&quot;">​</a></h3><ul><li>Die Standard-Einstellungen wurden angepasst und um fehlende Einträge ergänzt.</li><li>Das Layout der Ini-Dateien wurde überarbeitet. Es wurden Erläuterungen zu den einzelnen Optionen hinzugefügt.</li><li>Ini-Dateien der Vorgängerversion können ebenso weiterhin verwendet werden.</li></ul><h3 id="gs-ankreuzzeugnis-rtm" tabindex="-1">GS-AnkreuzZeugnis.rtm <a class="header-anchor" href="#gs-ankreuzzeugnis-rtm" aria-label="Permalink to &quot;GS-AnkreuzZeugnis.rtm&quot;">​</a></h3><ul><li>Eine Linie wurde für die Fächergruppe Deutsch ergänzt.</li></ul><h3 id="alle-zeugnisse-1" tabindex="-1">Alle Zeugnisse <a class="header-anchor" href="#alle-zeugnisse-1" aria-label="Permalink to &quot;Alle Zeugnisse&quot;">​</a></h3><ul><li>Bug bezüglich der Schulformempfehlung für den Eintrag „keine Empfehlung“ behoben.</li><li>Der Jahrgang wird je nach Angabe in der Ini-Datei nun auch für zieldifferente SuS ausgegeben.</li></ul><h3 id="gs-lernstandsbericht-hybridform-rtm-gs-lernstandsbericht-hybridform-rtm" tabindex="-1">GS-Lernstandsbericht_Hybridform.rtm, GS-Lernstandsbericht_Hybridform.rtm <a class="header-anchor" href="#gs-lernstandsbericht-hybridform-rtm-gs-lernstandsbericht-hybridform-rtm" aria-label="Permalink to &quot;GS-Lernstandsbericht_Hybridform.rtm, GS-Lernstandsbericht_Hybridform.rtm&quot;">​</a></h3><ul><li>In dem Passus „xxx besucht seit dd.mm.jjjj eine deutsche Schule“ wurde das Datum auf das Aufnahmedatum gesetzt (zuvor: Anmeldedatum)</li></ul><h2 id="version-14-12-2022" tabindex="-1">Version 14.12.2022 <a class="header-anchor" href="#version-14-12-2022" aria-label="Permalink to &quot;Version 14.12.2022&quot;">​</a></h2><h3 id="gs-ankreuzzeugnisse" tabindex="-1">GS-Ankreuzzeugnisse <a class="header-anchor" href="#gs-ankreuzzeugnisse" aria-label="Permalink to &quot;GS-Ankreuzzeugnisse&quot;">​</a></h3><ul><li>Überflüssiger Seitenumbruch, der bei der Verwendung des Zeugnisses für Jahrgangsstufe 4 beim Auslassen des Begründungstextes für den Wechsel nach Sek1 auftrat, wurde entfernt</li></ul><h2 id="version-14-10-2022" tabindex="-1">Version 14.10.2022 <a class="header-anchor" href="#version-14-10-2022" aria-label="Permalink to &quot;Version 14.10.2022&quot;">​</a></h2><h3 id="gs-ankreuzzeugnisse-1" tabindex="-1">GS-Ankreuzzeugnisse <a class="header-anchor" href="#gs-ankreuzzeugnisse-1" aria-label="Permalink to &quot;GS-Ankreuzzeugnisse&quot;">​</a></h3><ul><li><p>Wenn für ASV keine Ankreuzkompetenzen vorhanden waren, sondern nur ein Bemerkungstext, so wurde die Überschrift für ASV nicht korrekt dargestellt. Das ist nun behoben.</p></li><li><p>Es gibt Fälle, wo bei der Fachgruppe &quot;Deutsch&quot; (die ja aus mehreren Fächern bestehen kann) gewünscht wird, dass die &quot;Einzelfächer&quot; (Lesen, Rechtschreiben, Sprachgebrauch) zusammengehalten werden, nicht aber die Gruppe &quot;Deutsch&quot; insgesamt.</p></li><li><p>Bisher war es möglich, jahrgangsbezogen das &quot;Zusammenhalten&quot; der Fachgruppen über folgende Einträge in der Konfigurationsdatei zu steuern:<br> ZusammenhaltenE1=<br> ZusammenhaltenE2=<br> Zusammenhalten03=<br> Zusammenhalten04=</p><p>Beispiel<br> ZusammenhaltenE2=Deutsch;Englisch;Mathematik<br> Dabei wurde aber die Gruppe &quot;Deutsch&quot; als Ganzes zusammengehalten, was z.B. zu Seitenumbrüchen führen konnte, obwohl noch genug Platz für eines der Teilfächer vorhanden war. Nun kann über einen Eintrag &quot;Deutsch(einzeln)&quot; gesteuert werden, dass die Einzelfächer zusammengehalten werden, nicht aber die Fachgruppe insgesamt.</p><p>Beispiel<br> ZusammenhaltenE2=Deutsch(einzeln);Englisch;Mathematik<br> Wichtig: Die funktioniert derzeit nur für die Fachgruppe &quot;Deutsch&quot;</p></li></ul><h2 id="version-23-01-2021" tabindex="-1">Version 23.01.2021 <a class="header-anchor" href="#version-23-01-2021" aria-label="Permalink to &quot;Version 23.01.2021&quot;">​</a></h2><h3 id="gs-lernstandsbericht-hybridform-rtm" tabindex="-1">GS-Lernstandsbericht_Hybridform.rtm <a class="header-anchor" href="#gs-lernstandsbericht-hybridform-rtm" aria-label="Permalink to &quot;GS-Lernstandsbericht_Hybridform.rtm&quot;">​</a></h3><ul><li>Der zweispaltige &quot;Notenblock&quot; wurde komplett entfernt. Das hat zur Folge, dass die Bereiche [Notenzeugnisreihenfolge_Links] und [Notenzeugnisreihenfolge_Rechts] in der Konfigurationsdatei nicht mehr benötigt werden. Auch der Eintrag &quot;Noten2SpaltigAbJahrgang=&quot; im Bereich [Optionen] wird nicht mehr benötigt.</li></ul><h3 id="gs-hybridzeugnis-rtm" tabindex="-1">GS-HybridZeugnis.rtm <a class="header-anchor" href="#gs-hybridzeugnis-rtm" aria-label="Permalink to &quot;GS-HybridZeugnis.rtm&quot;">​</a></h3><ul><li>Einige kleiner Korrekturen/Anpassungen.</li></ul><h3 id="gs-ankreuzzeugnis-rtm-1" tabindex="-1">GS-AnkreuzZeugnis.rtm <a class="header-anchor" href="#gs-ankreuzzeugnis-rtm-1" aria-label="Permalink to &quot;GS-AnkreuzZeugnis.rtm&quot;">​</a></h3><ul><li>Die Vorlage erkennt nun automatisch, ob ein zusätzlicher Subreport &quot;Kompetenz_Erlaeuterung.rtm&quot; (mit Erläuterungen zu den Kompetenzstufen) vorhanden ist und fügt diesen dann als zusätzliches Blatt an. Die Vorlage &quot;GS-AnkreuzZeugnis_Mit_Erlaeuterung.rtm&quot; wird nicht mehr benötigt.</li></ul><h2 id="version-15-6-2020" tabindex="-1">Version 15.6.2020 <a class="header-anchor" href="#version-15-6-2020" aria-label="Permalink to &quot;Version 15.6.2020&quot;">​</a></h2><ul><li>Änderungen für Druck in Dokumentenverwaltung</li><li>Anpassung der Rechtshilfebelehrung (&quot;dehnen&quot;)</li><li>Separate Vorlage &quot;GS-AnkreuzZeugnis_Mit_Erlaeuterung.rtm&quot; (für Ausgabe eines Erläuterungsblattes am Ende) wird nicht mehr benötigt. Falls eine Datei &quot;Kompetenz_Erlaeuterung.rtm&quot; im Verzeichnis der Reportvorlage gefunden wird, wird diese automatsich am Ende jedes Zeugnisses geladen.</li></ul><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Grundschulzeugnisse_Versionsgeschichte_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5860.</p>',39)])])}const m=n(t,[["render",s]]);export{c as __pageData,m as default};
